                                                                                                                                                                                                                        
  CREATE TABLE "JW_AUDIT_LOGS"                                                                                                                                                                           
   (	"LOG_ID" NUMBER(20,0) GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 643508838382022 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE,     
	"TENANT_ID" NUMBER(20,0) DEFAULT 1 NOT NULL ENABLE,                                                                                                                                                                    
	"CREATED_BY" NVARCHAR2(256),                                                                                                                                                                                           
	"CREATION_DATE" DATE DEFAULT sysdate NOT NULL ENABLE,                                                                                                                                                                  
	"UPDATED_BY" NVARCHAR2(256),                                                                                                                                                                                           
	"UPDATE_DATE" DATE DEFAULT sysdate NOT NULL ENABLE,                                                                                                                                                                    
	"LOG_MODULE" VARCHAR2(128) NOT NULL ENABLE,                                                                                                                                                                            
	"LOG_TYPE" VARCHAR2(128) NOT NULL ENABLE,                                                                                                                                                                              
	"REMARK" CLOB,                                                                                                                                                                                                         
	 PRIMARY KEY ("LOG_ID")                                                                                                                                                                                                
  USING INDEX  ENABLE                                                                                                                                                                                                   
   ) ;                                                                                                                                                                                                                  

